package com.procurement.approvalhistory.controller;import com.procurement.approvalhistory.dto.response.*;import com.procurement.approvalhistory.service.*;import com.procurement.common.response.*;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/approval-histories")public class ApprovalHistoryController{private final ApprovalHistoryService service;public ApprovalHistoryController(ApprovalHistoryService s){service=s;}@GetMapping public ApiResponse<PageResponse<ApprovalHistoryResponse>>search(@RequestParam(required=false)Long purchaseRequestId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="performedAt")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(purchaseRequestId,PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort))));}@GetMapping("/{id}")public ApiResponse<ApprovalHistoryResponse>get(@PathVariable Long id){return ApiResponse.success(service.getById(id));}}
